const totalIncomeRaw =
  $node["Calculate Monthly Income"].json.total_income;

const totalIncome =
  Number(totalIncomeRaw || 0);

const amount =
  Number(
    $node["Extract Transaction Data"].json.amount || 0
  );

const category =
  $node["Extract Transaction Data"].json.category;

const formatRupiah = (num) =>
  new Intl.NumberFormat('id-ID').format(num);

return [
  {
    json: {
      category,
      amount,
      total_income: totalIncome,

      formatted_amount:
        formatRupiah(amount),

      formatted_total_income:
        formatRupiah(totalIncome)
    }
  }
];

const spendingRaw =
  $node["Get Monthly Spending"].json.total_spending;

const limitRaw =
  $node["Get Budget Limit"].json.limit_amount;

const category =
  $node["Parse Transaction"].json.category;

const spending = Number(spendingRaw || 0);
const limit = Number(limitRaw || 0);

const percentage =
  limit > 0
    ? Number(((spending / limit) * 100).toFixed(1))
    : 0;

const formatRupiah = (num) =>
  new Intl.NumberFormat('id-ID').format(num);

const remaining = limit - spending;
const filled = Math.min(10, Math.max(0, Math.round(percentage / 10)));

return [
  {
    json: {
      category,
      spending,
      limit,
      percentage,
      formatted_spending: formatRupiah(spending),
      formatted_limit: formatRupiah(limit),
      formatted_remaining: formatRupiah(Math.abs(remaining)),
      is_over: remaining < 0,
      bar: '▓'.repeat(filled) + '░'.repeat(10 - filled)
    }
  }
];

