try {
  const parsed = JSON.parse(raw);
  const list = Array.isArray(parsed) ? parsed : parsed.intents;
  if (Array.isArray(list)) intents = list;
} catch (e) {
  intents = [];
}

// 4. Keep only known intents, drop duplicates
intents = [...new Set(intents.filter(i => ALLOWED.includes(i)))];

return [{ json: { intents, raw_output: raw } }];

