      case 'bulk_delete': return '⚠️ Penghapusan massal tidak didukung.\n\nDemi keamanan, budget dihapus satu per satu. Sebutkan namanya.\n\nBudget yang ada:\n' + list + '\n\nContoh: "hapus budget food"';
      case 'name_required': return '⚠️ Sebutkan nama budget yang ingin diubah.\n\nBudget yang ada:\n' + list;
      case 'amount_required': return '⚠️ Nominalnya belum disebutkan.\n\nContoh: "tambah budget ' + (nm ?? 'food') + ' 100rb"';
      case 'nothing_to_update': return 'ℹ️ Tidak ada yang diubah. Sebutkan nama baru atau limit baru.\n\nContoh: "set budget food jadi 600rb"';
