};

const MONTHS = ['Januari', 'Februari', 'Maret', 'April', 'Mei', 'Juni', 'Juli', 'Agustus', 'September', 'Oktober', 'November', 'Desember'];
const fmtId = (y, m, d) => `${d} ${MONTHS[m - 1]} ${y}`;

// Checks a deadline and fixes what can be fixed safely.
// - not parseable / impossible month or year  -> { value: null }   (rejected)
// - day beyond the month length (31 Feb)       -> clamped to the last day, with a note
// - allowPartial (update): "2028" and "2028-06" are accepted as-is; the DB fills in the rest
const fixDate = (s, allowPartial) => {
  const t = String(s).trim();
  const yearOk = (y) => y >= 1900 && y <= 2200;

  if (allowPartial) {
    if (/^\d{4}$/.test(t)) return { value: yearOk(Number(t)) ? t : null };
    const pm = /^(\d{4})-(\d{2})$/.exec(t);
    if (pm) return { value: yearOk(Number(pm[1])) && Number(pm[2]) >= 1 && Number(pm[2]) <= 12 ? t : null };
  }

  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(t);
  if (!m) return { value: null };
  const y = Number(m[1]), mo = Number(m[2]), d = Number(m[3]);
  if (!yearOk(y) || mo < 1 || mo > 12 || d < 1 || d > 31) return { value: null };

  const last = new Date(Date.UTC(y, mo, 0)).getUTCDate();
  if (d <= last) return { value: t };

  const fixed = `${m[1]}-${m[2]}-${String(last).padStart(2, '0')}`;
  return {
    value: fixed,
    note: `⚠️ Tanggal ${fmtId(y, mo, d)} tidak ada, jadi deadline disesuaikan ke ${fmtId(y, mo, last)}.`
  };
};

