const setupItems = $("Check Validation (S)")
  .all()
  .filter(i => i.json.valid_status === "valid");
const rows = $("Merge (S)").all().map(i => i.json);

const rp = (n) => "Rp" + new Intl.NumberFormat("id-ID").format(Number(n ?? 0));
const same = (a, b) => a != null && b != null && String(a).toLowerCase() === String(b).toLowerCase();
const dateOrDash = (d) => (d ? String(d).slice(0, 10) : "Belum ditentukan");

const bar = (current, target) => {
  if (!(Number(target) > 0)) return "Belum memiliki target";
  const pct = Math.round((Number(current) / Number(target)) * 100);
  const filled = Math.max(0, Math.min(10, Math.round(pct / 10)));
  return "▓".repeat(filled) + "░".repeat(10 - filled) + " " + pct + "%";
};

const out = [];
for (const item of setupItems) {
  const data = item.json;
  const action = data.action;

  const s = rows.find(r => same(r.old_name ?? r.savings_name, data.name) || same(r.savings_name, data.name));
  if (!s) continue;

  const lines = [];
  const summary = () => {
    lines.push("");
    lines.push(`📅 Deadline: ${dateOrDash(s.target_date_text)}`);
    lines.push(`🪙 Terkumpul: ${rp(s.current_amount)}`);
    lines.push(`📊 Progress: ${bar(s.current_amount, s.target_amount)}`);
  };

  if (action === "create") {
    lines.push("✅ Savings dibuat", "");
    lines.push(`🎯 ${s.savings_name}`);
    lines.push(`💰 Target: ${rp(s.target_amount)}`);
    summary();
    if (data.date_note) lines.push("", data.date_note);

  } else if (action === "increase" || action === "decrease") {
    const up = action === "increase";
    const delta = Number(data.amount ?? 0);
    const newT = Number(s.target_amount);
    const oldT = up ? newT - delta : newT + delta;

    lines.push(up ? "✅ Target savings dinaikkan" : "✅ Target savings diturunkan", "");
    lines.push(`🎯 ${s.savings_name}`);
    lines.push(`💰 Target: ${rp(oldT)} ➜ ${rp(newT)} (${up ? "+" : "-"}${rp(delta)})`);
    summary();

  } else if (action === "update") {
    const oldName = s.old_name ?? data.name;
    const oldT = Number(s.old_target_amount ?? s.target_amount);
    const newT = Number(s.target_amount);
    const oldD = s.old_target_date_text ?? null;
    const newD = s.target_date_text ?? null;
    const nameChanged = oldName !== s.savings_name;
    const targetChanged = oldT !== newT;
    const dateChanged = (oldD ?? "") !== (newD ?? "");

    // perubahan relatif (naikkan/kurangi) yang dilipat ke update ini
    const delta = Number(data.amount_delta ?? 0);
    const showDelta = delta !== 0 && data.new_amount == null;
    const deltaText = showDelta ? ` (${delta > 0 ? "+" : "-"}${rp(Math.abs(delta))})` : "";

    lines.push("✅ Savings diperbarui", "");
    lines.push(`🎯 ${nameChanged ? `${oldName} ➜ ${s.savings_name}` : s.savings_name}`);
    lines.push(`💰 Target: ${targetChanged ? `${rp(oldT)} ➜ ${rp(newT)}${deltaText}` : rp(newT)}`);
    lines.push("");
    lines.push(`📅 Deadline: ${dateChanged ? `${dateOrDash(oldD)} ➜ ${dateOrDash(newD)}` : dateOrDash(newD)}`);
    lines.push(`🪙 Terkumpul: ${rp(s.current_amount)}`);
    lines.push(`📊 Progress: ${bar(s.current_amount, s.target_amount)}`);
    if (data.date_note) lines.push("", data.date_note);
    if (!nameChanged && !targetChanged && !dateChanged) {
      lines.push("", "ℹ️ Datanya sama dengan sebelumnya, tidak ada yang berubah.");
    }

  } else if (action === "delete") {
    lines.push("🗑️ Savings dihapus", "");
    lines.push(`🎯 ${s.savings_name}`);
    lines.push(`💰 Target: ${rp(s.target_amount)}`);
    lines.push(`🪙 Terkumpul terakhir: ${rp(s.current_amount)}`);

  } else {
    lines.push("✅ Selesai");
  }

  out.push({ json: { action, message: lines.join("\n") } });
}
return out;

