const ALLOWED = ['cash', 'bank', 'credit_card', 'e-wallet', 'loan', 'other'];
const ALIAS = {
  'ewallet': 'e-wallet', 'e wallet': 'e-wallet', 'dompet digital': 'e-wallet',
  'tunai': 'cash', 'kartu kredit': 'credit_card', 'credit card': 'credit_card',
  'pinjaman': 'loan', 'utang': 'loan', 'hutang': 'loan'
};

// "delete all accounts" -> empty name or a bulk-action keyword; never perform bulk deletion
const BULK = /\b(semua|semuanya|seluruh|segala|all|every|everything)\b/i;
// a name that is only a type word ("savings", "budget", "akun") means the parser dropped "semua"
const TYPE_ONLY = /^(budgets?|kategori|categor(?:y|ies)|savings?|tabungan|goals?|akun|akun-akun|accounts?|rekening)$/i;
let rawMessage = '';
try { rawMessage = String($('Data Input').first().json.message ?? ''); } catch (err) { rawMessage = ''; }
const clauseFor = (name) => {
  const n = String(name ?? '').toLowerCase();
  const parts = rawMessage.split(/[,;\n]|\s+(?:dan|lalu|terus|kemudian|and|then)\s+/i);
  return parts.find(p => n && p.toLowerCase().includes(n)) ?? rawMessage;
};

const isEmpty = (v) => v == null || v === 'null' || v === '';

const clean = (v) => {
  if (v == null || v === 'null' || v === '') return null;
  const t = String(v).trim().toLowerCase();
  return ALIAS[t] ?? t;
};

const existenceItems = $input.all();
const entityItems = $('Check Entities').all();

return existenceItems.map((item, index) => {
  const entity = entityItems[index].json;
  const a = entity.action;
  const type = clean(entity.acc_type);
  const newType = clean(entity.new_acc_type);
  const exists = item.json.category_exists;
  const nameStr = isEmpty(entity.name) ? '' : String(entity.name).trim();

  // balance after the change; cash/bank/e-wallet/other cannot go below 0
  // (credit_card and loan may legitimately be negative)
  const cur = item.json.current_amount == null ? null : Number(item.json.current_amount);
  const effType = newType || item.json.current_type;
  const canBeNegative = ['credit_card', 'loan'].includes(effType);
  let nextAmount = null;
  if (cur !== null && !canBeNegative) {
    if ((a === 'increase' || a === 'decrease') && !isEmpty(entity.amount)) {
      nextAmount = cur + (a === 'decrease' ? -1 : 1) * Number(entity.amount);
    } else if (a === 'update' && (!isEmpty(entity.new_amount) || !isEmpty(entity.amount_delta))) {
      nextAmount = (isEmpty(entity.new_amount) ? cur : Number(entity.new_amount)) + (Number(entity.amount_delta) || 0);
    }
  }


  let reason = null;
  if (a === 'create') {
    if (isEmpty(entity.name) || isEmpty(entity.amount) || type == null) reason = 'incomplete';
    else if (!ALLOWED.includes(type)) reason = 'bad_type';
    else if (exists) reason = 'duplicate';
  } else if (isEmpty(entity.name)) {
    reason = a === 'delete' ? 'bulk_delete' : 'name_required';
  } else if (a === 'delete' && !exists && (BULK.test(nameStr) || TYPE_ONLY.test(nameStr) || BULK.test(clauseFor(nameStr)))) {
    reason = 'bulk_delete';
  } else if (!exists) {
    reason = 'not_found';
  } else if ((a === 'increase' || a === 'decrease') && isEmpty(entity.amount)) {
    reason = 'amount_required';
  } else if (nextAmount !== null && nextAmount < 0) {
    reason = 'below_zero';
  } else if (a === 'update' && newType && !ALLOWED.includes(newType)) {
    reason = 'bad_type';
  } else if (a === 'update' && isEmpty(entity.new_name) && isEmpty(entity.new_amount) && !newType && isEmpty(entity.amount_delta)) {
    reason = 'nothing_to_update';
  } else if (a === 'update' && item.json.new_name_taken) {
    reason = 'duplicate_new';
  }

  return {
    json: {
      ...entity, ...item.json,
      acc_type: type, new_acc_type: newType,
      valid_status: reason ? 'invalid' : 'valid',
      invalid_reason: reason
    }
  };
});

