    lines.push(`💰 Saldo: ${balChanged ? `${rp(oldBal)} ➜ ${rp(newBal)}${deltaText}` : rp(newBal)}`);

    if (!nameChanged && !typeChanged && !balChanged) {
      lines.push("", "ℹ️ Datanya sama dengan sebelumnya, tidak ada yang berubah.");
    }

  } else if (action === "delete") {
    lines.push("🗑️ Akun dihapus", "");
    lines.push(`${icon} ${acc.account_name}`);
    lines.push(`🏷️ Tipe: ${acc.account_type}`);
    lines.push(`💰 Saldo terakhir: ${rp(acc.balance)}`);

  } else {
    lines.push("✅ Selesai");
  }

  return { json: { action, message: lines.join("\n") } };
});

